import { INestApplication } from '@nestjs/common';
import request from 'supertest';
import { AppModule } from '../src/app.module';
import { PrismaClient } from '@prisma/client';

export const prisma = new PrismaClient();

let TestModule: typeof import('@nestjs/testing');

async function loadTestModule() {
  if (!TestModule) {
    TestModule = await import('@nestjs/testing');
  }
  return TestModule;
}

export async function createTestApp(): Promise<INestApplication> {
  const { Test } = await loadTestModule();
  const moduleFixture = await Test.createTestingModule({
    imports: [AppModule],
  }).compile();

  const app = moduleFixture.createNestApplication();
  await app.init();
  return app;
}

export interface TestUser {
  id: string;
  email: string;
  password: string;
  name: string;
  accessToken: string;
}

export interface TestForm {
  id: string;
  name: string;
  slug: string;
  workspaceId: string;
}

export async function registerAndLogin(app: INestApplication, email: string, password = 'Test1234', name = 'Test User'): Promise<TestUser> {
  const registerRes = await request(app.getHttpServer())
    .post('/api/auth/register')
    .send({ email, password, name })
    .expect(201);

  const loginRes = await request(app.getHttpServer())
    .post('/api/auth/login')
    .send({ email, password })
    .expect(200);

  const cookie = loginRes.headers['set-cookie'];
  const accessToken = cookie?.[0]?.split(';')[0]?.replace('jwt=', '') || '';

  return {
    id: '',
    email,
    password,
    name,
    accessToken,
  };
}

export async function createForm(app: INestApplication, token: string, data: { name: string; description?: string }): Promise<TestForm> {
  const res = await request(app.getHttpServer())
    .post('/api/forms')
    .set('Cookie', `jwt=${token}`)
    .send(data)
    .expect(201);

  return res.body;
}

export async function publishForm(app: INestApplication, token: string, formId: string) {
  return request(app.getHttpServer())
    .post(`/api/forms/${formId}/publish`)
    .set('Cookie', `jwt=${token}`)
    .expect(200);
}

export async function saveFields(app: INestApplication, token: string, formId: string, fields: any[]) {
  return request(app.getHttpServer())
    .post(`/api/forms/${formId}/fields`)
    .set('Cookie', `jwt=${token}`)
    .send({ fields })
    .expect(200);
}

export async function saveRules(app: INestApplication, token: string, formId: string, rules: any[]) {
  return request(app.getHttpServer())
    .post(`/api/forms/${formId}/rules`)
    .set('Cookie', `jwt=${token}`)
    .send({ rules })
    .expect(200);
}

export async function submitPublicForm(app: INestApplication, slug: string, answers: { fieldId: string; value: any }[]) {
  return request(app.getHttpServer())
    .post(`/api/public/forms/${slug}/submissions`)
    .send({ answers })
    .expect(201);
}

export async function cleanupTestData() {
  await prisma.submissionAnswer.deleteMany();
  await prisma.submission.deleteMany();
  await prisma.formVersion.deleteMany();
  await prisma.formRule.deleteMany();
  await prisma.formField.deleteMany();
  await prisma.form.deleteMany();
  await prisma.workspace.deleteMany();
  await prisma.user.deleteMany();
  await prisma.formAnalytics.deleteMany();
}

export function extractUserIdFromToken(token: string): string {
  try {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
    return payload.sub;
  } catch {
    return '';
  }
}